            modelObserved = e.payload?.modelObserved ?? e.payload?.model ?? modelObserved;
            if (e.actor === 'worker') {
              const nativeId = e.payload?.threadId ?? e.payload?.sessionId;
              if (typeof nativeId === 'string' && nativeId.length > 0) {
