 171	  /**
 172	   * @param {{taskType:string}} task
 173	   * @param {RouteCandidate[]} candidates
 174	   * @param {{now?:number}} [opts]
 175	   * @returns {string|null}
 176	   */
 177	  pick(task, candidates, opts = {}) {
 178	    const nowMs = this._resolveNow(opts.now);
 179	    const taskType = task.taskType;
 180	
 181	    const eligible = candidates.filter((c) => c.inFlight < c.concurrencyCeiling);
 182	    if (eligible.length === 0) return null;
 183	
 184	    const effectiveMode = this._effectiveMode(taskType, eligible, nowMs);
 185	
 186	    if (effectiveMode === 'round-robin') {
 187	      return this._pickRoundRobin(taskType, eligible);
 188	    }
 189	
 190	    return this._pickAdaptive(taskType, eligible, nowMs);
 191	  }
 192	
 193	  _effectiveMode(taskType, eligible, nowMs) {
 194	    if (this.mode === 'round-robin') return 'round-robin';
 195	    if (this.mode === 'adaptive') return 'adaptive';
 196	    // mode === 'auto'
 197	    const totalDecayedCount = eligible.reduce((sum, c) => {
 198	      const bucket = this._candidateBucket(c, taskType);
 199	      return sum + decayedStat(bucket, nowMs, this.halfLifeMs).count;
 200	    }, 0);
 201	    return totalDecayedCount < this.minSamplesForAdaptive ? 'round-robin' : 'adaptive';
 202	  }
 203	
 204	  _pickRoundRobin(taskType, eligible) {
 205	    const cursor = this._rrCursor.get(taskType) ?? 0;
 206	    const idx = cursor % eligible.length;
 207	    this._rrCursor.set(taskType, cursor + 1);
 208	    return eligible[idx].modelVersion;
 209	  }
 210	
 211	  _pickAdaptive(taskType, eligible, nowMs) {
 212	    // Touch (seed, without mutating storage beyond the seed-on-first-touch
 213	    // semantics already defined in _ensureBucket) each eligible candidate's
 214	    // bucket so scoring/seeding is consistent, then score using decayed
 215	    // projections read at `nowMs`.
 216	    const decoratedCandidates = eligible.map((c) => {
 217	      const bucket = this._candidateBucket(c, taskType)
 218	        ?? this._ensureBucket(c.family, c.modelVersion, taskType, nowMs);
 219	      return { candidate: c, bucket };
 220	    });
  85	  } }, 'web:u:s');
